  {"name": "existing packages are replaced and sorted", "script": 'runArtifactRustPackageMain(d, "art", { packages: ["art", "art-b"] })\n', "artifact": "art", "additions": ["art-a"], "expected": 'runArtifactRustPackageMain(d, "art", { packages: ["art", "art-a", "art-b"] })\n'},
